const base = $('Resolve Matter').first().json;
let raw = $input.first().json;
if (raw && raw.output) raw = raw.output;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }

function fail(reason) {
  return [{ json: { ...base, plan_valid: false, failure_reason: reason,
    matter_status: 'FAILED', requires_information: false, actions: [], questions: [] } }];
}

if (!raw || typeof raw !== 'object') return fail('Planner returned no parsable JSON.');
if (!PLAYBOOKS[raw.playbook_id]) return fail('Planner returned an unknown playbook_id: ' + String(raw.playbook_id));
if (!Array.isArray(raw.missing_facts)) return fail('missing_facts was not an array.');
if (!Array.isArray(raw.proposed_actions)) return fail('proposed_actions was not an array.');
if (typeof raw.title !== 'string' || !raw.title.trim()) return fail('Planner returned no title.');

const pb = PLAYBOOKS[raw.playbook_id];

// Merge new facts over recorded facts. Never let an empty value overwrite a recorded one.
let facts = {};
try { facts = JSON.parse(base.known_facts_json || '{}'); } catch (e) { facts = {}; }
const incoming = (raw.known_facts && typeof raw.known_facts === 'object') ? raw.known_facts : {};
for (const [k, v] of Object.entries(incoming)) {
  if (v === null || v === undefined) continue;
  const s = String(v).trim();
  if (!s || s.toUpperCase() === 'MISSING' || s.toUpperCase() === 'UNKNOWN') continue;
  facts[k] = s;
}

// Any required fact of the playbook that is not in facts is MISSING. This is enforced here,
// not trusted to the model.
const enforcedMissing = new Set(raw.missing_facts.map(String));
for (const rf of (pb.required_facts || [])) {
  if (!Object.prototype.hasOwnProperty.call(facts, rf)) enforcedMissing.add(rf);
}
const missing = Array.from(enforcedMissing);

const requiresInfo = raw.requires_information === true || missing.length > 0;

// Approval is forced on for any externally directed action type. The model cannot switch it off.
const MUST_APPROVE = ['SEND_DOCUMENT','CONTACT_INSURER','SEND_DEMAND','FOLLOW_UP','SEND_EMAIL','FILE_DOCUMENT'];
const stamp = new Date().toISOString();
const actions = (raw.proposed_actions || []).slice(0, 8).map((a, i) => {
  const type = String(a.action_type || 'COLLECT_FACTS').toUpperCase();
  const external = MUST_APPROVE.includes(type) || String(a.channel || '').toUpperCase() === 'GMAIL';
  const seq = String(i + 1).padStart(3, '0');
  const dueRaw = String(a.due_at || '').trim();
  return {
    action_id: base.matter_id.replace('MAT-', 'ACT-') + '-' + seq,
    matter_id: base.matter_id,
    action_type: type,
    description: String(a.description || '').slice(0, 900),
    status: (Array.isArray(a.depends_on) && a.depends_on.length) ? 'BLOCKED' : 'READY',
    priority: ['HIGH','MEDIUM','LOW'].includes(String(a.priority || '').toUpperCase())
      ? String(a.priority).toUpperCase() : 'MEDIUM',
    depends_on_json: JSON.stringify((Array.isArray(a.depends_on) ? a.depends_on : [])
      .map(n => base.matter_id.replace('MAT-', 'ACT-') + '-' + String(n).padStart(3, '0'))),
    recipient: String(a.recipient || ''),
    channel: external ? 'GMAIL' : (String(a.channel || 'NONE').toUpperCase()),
    requires_approval: external ? 'TRUE' : (a.requires_approval === true ? 'TRUE' : 'FALSE'),
    draft_id: '',
    approval_id: '',
    due_at: dueRaw,
    deadline_basis: dueRaw ? (String(a.deadline_basis || '') || 'UNVERIFIED_ESTIMATE') : '',
    blocked_reason: (Array.isArray(a.depends_on) && a.depends_on.length) ? 'Waiting on an earlier action.' : '',
    idempotency_key: base.matter_id + '|' + seq,
    created_at: stamp,
    updated_at: stamp,
  };
});

const risks = Array.from(new Set([].concat(
  Array.isArray(raw.risk_flags) ? raw.risk_flags.map(String) : [],
  requiresInfo ? ['MATERIAL_FACTS_MISSING'] : [],
  raw.requires_human_review === true ? ['REQUIRES_HUMAN_REVIEW'] : []
)));

// D10: Case-insensitive question deduplication.
// new Set() uses strict equality so capitalisation differences (e.g. "owner's" vs "Owner's")
// allowed semantic duplicates to survive. We now normalise to lowercase before the seen-check
// and keep the first occurrence, preserving its original wording for display.
const questions = requiresInfo
  ? (() => {
      const seen = new Set();
      return [].concat(
        Array.isArray(raw.clarification_questions) ? raw.clarification_questions.map(String) : [],
        missing.map(m => (pb.intake_questions.find(q => q.toLowerCase().includes(m.split('_')[0])) || ('What is the ' + m.replace(/_/g, ' ') + '?')))
      ).filter(q => {
        const key = q.trim().toLowerCase();
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      }).slice(0, 10);
    })()
  : [];

const status = requiresInfo ? 'NEEDS_INFORMATION' : 'CLASSIFIED';

return [{ json: {
  ...base,
  plan_valid: true,
  failure_reason: '',
  title: String(raw.title).slice(0, 200),
  playbook_id: raw.playbook_id,
  playbook_name: pb.name,
  jurisdiction: String(raw.jurisdiction || pb.jurisdiction),
  facts_json: JSON.stringify(facts),
  missing_facts_json: JSON.stringify(missing),
  required_evidence_json: JSON.stringify(Array.isArray(raw.required_evidence) ? raw.required_evidence : []),
  risk_flags_json: JSON.stringify(risks),
  matter_status: status,
  requires_information: requiresInfo,
  requires_human_review: raw.requires_human_review === true,
  owner_summary: String(raw.owner_summary || '').slice(0, 900),
  questions,
  actions,
  source_policy_json: JSON.stringify(pb.source_policy || []),
}}];

